{"code": "const files = await glob("src/data/*.txt");
const results = [];
for (const f of files) {
  const content = (await readFile(f)).trim();
  const [name, scoreStr] = content.split(",").map(s => s.trim());
  const score = Number(scoreStr);
  const meta = {
    name,
    score,
    passed: score >= 60
  };
  const metaPath = f.replace(/\.txt$/, ".meta.json");
  await writeFile(metaPath, JSON.stringify(meta));
  results.push(`${metaPath}: ${JSON.stringify(meta)}`);
}
console.log(results.join("\n"));"}
